fr:mainmatter.fr:tex:
\begin {align*}
  \mathbb {P}_{\theta }(z', b' = 0 \mid  z) &= \delta _{\{z' = z\}} (1 - \psi _{\theta }(s_{t + 1}, z)) \\
  \mathbb {P}_{\theta }(z', b' = 1 \mid  z) &= \eta _{\theta }(z' \mid  s_{t + 1}) \psi _{\theta }(s_{t + 1}, z)
.\end {align*}

\begin {align*}
\mathbb {P}_{\theta }(s_{t + 1}, a_{t + 1} \mid  z') &= \pi _{\theta }(a_{t + 1} \mid  s_{t + 1}, z') p(s_{t + 1} \mid  s_t, a_t)
.\end {align*}

